const input = $json || {};

const sampleRecommendations = [
  {
    id: 'social-1',
    title: 'International Social Mixer',
    category: 'social',
    source: 'manual_test',
    location: 'Dubai Marina',
    estimatedCost: 120,
    currency: 'AED',
    confidence: 0.90,
    reason: 'Strong social fit and easy to attend alone.',
    rawScores: {
      calendarCompatibility: 9,
      travelConvenience: 7,
      socialQuality: 10,
      audienceFit: 9,
      fitnessValue: 1,
      growthValue: 6,
      networkingValue: 9,
      organicConnectionPotential: 9,
      funNovelty: 8,
      valueForMoney: 7,
      soloFriendly: 9
    }
  },
  {
    id: 'fitness-1',
    title: 'Boxing Class',
    category: 'fitness',
    source: 'manual_test',
    location: 'Palm Jumeirah',
    estimatedCost: 0,
    currency: 'AED',
    confidence: 0.95,
    reason: 'Supports weekly fitness consistency.',
    rawScores: {
      calendarCompatibility: 8,
      travelConvenience: 10,
      socialQuality: 5,
      audienceFit: 7,
      fitnessValue: 10,
      growthValue: 8,
      networkingValue: 3,
      organicConnectionPotential: 3,
      funNovelty: 6,
      valueForMoney: 10,
      soloFriendly: 10
    }
  },
  {
    id: 'social-1-duplicate',
    title: 'International Social Mixer',
    category: 'social',
    source: 'manual_test',
    location: 'Dubai Marina',
    estimatedCost: 120,
    currency: 'AED',
    confidence: 0.70,
    reason: 'Duplicate test item.',
    rawScores: {
      calendarCompatibility: 8,
      travelConvenience: 7,
      socialQuality: 9,
      audienceFit: 8,
      fitnessValue: 1,
      growthValue: 5,
      networkingValue: 8,
      organicConnectionPotential: 8,
      funNovelty: 7,
      valueForMoney: 6,
      soloFriendly: 8
    }
  }
];

let recommendations = [];

if (Array.isArray(input.recommendations)) {
  recommendations = input.recommendations;
} else if (Array.isArray(input.result?.recommendations)) {
  recommendations = input.result.recommendations;
} else if (Array.isArray(input.agentResponses)) {
  recommendations = input.agentResponses.flatMap(response =>
    Array.isArray(response?.result?.recommendations)
      ? response.result.recommendations
      : Array.isArray(response?.recommendations)
        ? response.recommendations
        : []
  );
} else {
  recommendations = sampleRecommendations;
}

return [{
  json: {
    request: input.request || {
      text: 'Bu akşam ne yapayım?',
      channel: 'manual_test'
    },
    context: input.context || {
      derivedContext: {
        calendarLoad: 'low',
        needsMoreSocial: true,
        needsMoreFitness: true
      }
    },
    recommendations,
    metadata: input.metadata || {
      correlationId: `recommendation-${Date.now()}`,
      testMode: true
    }
  }
}];

const input = $json || {};
const recommendations = Array.isArray(input.recommendations)
  ? input.recommendations
  : [];

const context = input.context || {};
const derived =
  context.derivedContext ||
  context.derived ||
  {};

const clamp = (value, min = 0, max = 10) =>
  Math.max(min, Math.min(max, Number(value ?? 0)));

const weights = {
  calendarCompatibility: 15,
  travelConvenience: 10,
  socialQuality: 15,
  audienceFit: 10,
  fitnessValue: 8,
  growthValue: 8,
  networkingValue: 8,
  organicConnectionPotential: 8,
  funNovelty: 7,
  valueForMoney: 6,
  soloFriendly: 5
};

const logs = [];
const rejected = [];
const normalized = [];

for (let index = 0; index < recommendations.length; index++) {
  const source = recommendations[index] || {};

  const title = String(source.title || '').trim();

  if (!title) {
    rejected.push({
      index,
      reason: 'missing_title',
      item: source
    });
    continue;
  }

  const rawScores = source.rawScores || source.scores || {};

  let score = 0;

  for (const [criterion, weight] of Object.entries(weights)) {
    score += clamp(rawScores[criterion]) * (weight / 10);
  }

  let contextAdjustment = 0;
  const contextReasons = [];

  if (
    derived.needsMoreSocial === true &&
    ['social', 'networking', 'dating'].includes(
      String(source.category || '').toLowerCase()
    )
  ) {
    contextAdjustment += 6;
    contextReasons.push('Weekly social target is below goal.');
  }

  if (
    derived.needsMoreFitness === true &&
    ['fitness', 'sports', 'wellness'].includes(
      String(source.category || '').toLowerCase()
    )
  ) {
    contextAdjustment += 6;
    contextReasons.push('Weekly fitness target is below goal.');
  }

  if (
    derived.calendarLoad === 'high' &&
    !['recovery', 'wellness'].includes(
      String(source.category || '').toLowerCase()
    )
  ) {
    contextAdjustment -= 8;
    contextReasons.push('Calendar load is high.');
  }

  if (
    derived.calendarLoad === 'high' &&
    ['recovery', 'wellness'].includes(
      String(source.category || '').toLowerCase()
    )
  ) {
    contextAdjustment += 8;
    contextReasons.push('Recovery is prioritized because calendar load is high.');
  }

  if (
    derived.isMondayOrTuesday === true &&
    derived.commuteConstraint?.active === true &&
    source.start
  ) {
    const eventStart = new Date(source.start);

    if (!Number.isNaN(eventStart.getTime())) {
      const formatter = new Intl.DateTimeFormat('en-GB', {
        timeZone: 'Asia/Dubai',
        hour: '2-digit',
        minute: '2-digit',
        hour12: false
      });

      const [hour, minute] = formatter
        .format(eventStart)
        .split(':')
        .map(Number);

      const startMinutes = hour * 60 + minute;
      const earliest = 19 * 60 + 30;

      if (startMinutes < earliest) {
        contextAdjustment -= 20;
        contextReasons.push(
          'Event starts too early for the Abu Dhabi to Dubai commute.'
        );
      }
    }
  }

  const penalty = Math.max(
    0,
    Number(source.penalty || source.rawScores?.penalty || 0)
  );

  const confidence = Math.max(
    0,
    Math.min(1, Number(source.confidence ?? 0.5))
  );

  const confidenceAdjustment =
    confidence >= 0.85 ? 3 :
    confidence < 0.50 ? -8 :
    0;

  const finalScore = Math.max(
    0,
    Math.min(
      100,
      Math.round(
        score +
        contextAdjustment +
        confidenceAdjustment -
        penalty
      )
    )
  );

  const classification =
    finalScore >= 85 ? 'Must Go' :
    finalScore >= 70 ? 'Strong Match' :
    finalScore >= 55 ? 'Good Alternative' :
    'Do Not Recommend';

  normalized.push({
    id:
      source.id ||
      `recommendation-${Date.now()}-${index}`,
    title,
    category:
      String(source.category || 'general'),
    source:
      String(source.source || 'unknown'),
    sourceUrl:
      source.sourceUrl || null,
    start:
      source.start || null,
    end:
      source.end || null,
    location:
      source.location || null,
    estimatedCost:
      source.estimatedCost ?? null,
    currency:
      source.currency || 'AED',
    confidence,
    reason:
      source.reason || '',
    rawScores,
    score: finalScore,
    classification,
    contextAdjustment,
    contextReasons,
    requiresApproval:
      Boolean(source.requiresApproval),
    approvalType:
      source.approvalType || null,
    metadata:
      source.metadata || {}
  });
}

const normalizeKey = item =>
  [
    item.title.toLocaleLowerCase('tr-TR').trim(),
    String(item.location || '').toLocaleLowerCase('tr-TR').trim(),
    String(item.start || '').slice(0, 16)
  ].join('|');

const deduplicatedMap = new Map();

for (const item of normalized) {
  const key = normalizeKey(item);
  const existing = deduplicatedMap.get(key);

  if (!existing || item.score > existing.score) {
    if (existing) {
      logs.push({
        level: 'info',
        message: 'Duplicate recommendation replaced by higher-scoring item.',
        details: {
          title: item.title,
          retainedScore: item.score,
          removedScore: existing.score
        }
      });
    }

    deduplicatedMap.set(key, item);
  } else {
    logs.push({
      level: 'info',
      message: 'Duplicate recommendation removed.',
      details: {
        title: item.title,
        retainedScore: existing.score,
        removedScore: item.score
      }
    });
  }
}

const ranked = [...deduplicatedMap.values()]
  .sort((a, b) => {
    if (b.score !== a.score) return b.score - a.score;
    return b.confidence - a.confidence;
  })
  .map((item, index) => ({
    rank: index + 1,
    ...item
  }));

const recommended = ranked.filter(item => item.score >= 55);
const topRecommendations = recommended.slice(0, 3);

const approvalRequests = topRecommendations
  .filter(item => item.requiresApproval)
  .map(item => ({
    type:
      item.approvalType ||
      'recommendation_action',
    status: 'proposed',
    recommendationId: item.id,
    summary: `Approval required for: ${item.title}`,
    payload: item
  }));

return [{
  json: {
    success: true,
    result: {
      recommendationCount: recommendations.length,
      validRecommendationCount: normalized.length,
      deduplicatedCount: ranked.length,
      recommendedCount: recommended.length,
      topRecommendations,
      allRankedRecommendations: ranked,
      rejectedRecommendations: rejected
    },
    memoryUpdates: topRecommendations.map(item => ({
      type: 'recommendation_history',
      operation: 'append',
      payload: {
        id: item.id,
        title: item.title,
        category: item.category,
        score: item.score,
        classification: item.classification,
        status: 'proposed',
        createdAt: new Date().toISOString()
      }
    })),
    approvalRequests,
    logs: [
      {
        timestamp: new Date().toISOString(),
        workflow: 'Concierge OS - Recommendation Engine',
        level: rejected.length ? 'warning' : 'info',
        correlationId:
          input.metadata?.correlationId || '',
        message:
          `Ranked ${ranked.length} unique recommendations.`,
        details: {
          inputCount: recommendations.length,
          rejectedCount: rejected.length,
          duplicateLogCount: logs.length
        }
      },
      ...logs.map(log => ({
        timestamp: new Date().toISOString(),
        workflow: 'Concierge OS - Recommendation Engine',
        correlationId:
          input.metadata?.correlationId || '',
        ...log
      }))
    ],
    nextAction: {
      type:
        approvalRequests.length
          ? 'evaluate_approval'
          : 'format_notification',
      targetWorkflow:
        approvalRequests.length
          ? 'Concierge OS - Approval Engine'
          : 'Concierge OS - Notification Engine'
    },
    error: null
  }
}];
